{"script":"cat << 'EOF' > process_inventory.py
import os

raw_listing = "temp_var_inventory/raw_listing.txt"
error_log = "temp_var_inventory/errors.log"
output_file = "temp_var_inventory/file_list.txt"

regular_files = set()

with open(raw_listing, 'r') as f, open(error_log, 'a') as err:
    for line in f:
        line = line.strip()
        if not line:
            continue
        # Last character is the type, everything before is the path
        parts = line.rsplit(' ', 1)
        if len(parts) != 2:
            continue
        path, ftype = parts

        if ftype == 'f':
            regular_files.add(os.path.abspath(path))
        elif ftype == 'l':
            try:
                target = os.path.realpath(path)
                if os.path.isfile(target):
                    regular_files.add(target)
                elif not os.path.exists(target):
                    err.write(f"Unresolved link: {path} -> {target}\n")
            except Exception as e:
                err.write(f"Error resolving {path}: {e}\n")

with open(output_file, 'w') as f:
    for path in sorted(regular_files):
        f.write(path + '\n')

print(len(regular_files))
EOF
python3 process_inventory.py
"}
